import {companionDays,petEditor} from './pet-profile.js';
// Figma-grounded layouts: 3420/3572, 2917, 3290, 3888, 2978, 3346, 3377, 1682:441.
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const image=(id,cls='',style='')=>`<img class="ui-asset ${cls}" src="./assets/screens/${id.replace(':','-')}.svg" alt="" data-figma-asset="${id}" ${style?`style="${style}"`:''}>`;
const onb=(id,cls='')=>`<img class="ui-asset ${cls}" src="./assets/onboarding/1667-${id}.svg" alt="">`;
const at=(id,x,y,cls='')=>image(id,`ui-at ${cls}`,`left:${x}px;top:${y}px`);
const chevron=()=>image('1667:3477','ui-chevron');
const day=t=>new Date(t).toLocaleDateString('zh-CN',{month:'long',day:'numeric'}).replace(/\s/g,'');
const clock=t=>new Date(t).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false});
const local=t=>{const d=new Date(t);return new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
const label=a=>a==='驱虫'?'体外驱虫':a;
export function petSubtitle(p){if(!p)return '先添加一只宠物';let age='';if(p.birthday){const b=new Date(p.birthday),now=new Date();let years=now.getFullYear()-b.getFullYear();if(now.getMonth()<b.getMonth()||(now.getMonth()===b.getMonth()&&now.getDate()<b.getDate()))years--;age=years>0?`${years}岁`:'不到1岁';}return [p.breed||p.kind,age,p.neutered?'已绝育':''].filter(Boolean).join(' · ');}
export function avatar(p,cls=''){return `<span class="ui-avatar ${cls}">${p?.avatar?`<img src="${E(p.avatar)}" alt="${E(p.name)}的头像">`:p?.kind==='狗狗'?'<img class="ui-asset ui-dog-avatar" src="./assets/dog/1700-1951.svg" alt="狗狗">':image(p?.avatarAsset||'1667:3948')}</span>`;}
function petCard(p){return `<div class="ui-pet-card">${image('1667:3371','ui-surface')}${avatar(p)}<div><strong>${E(p?.name||'选择宠物')}</strong><small>${E(petSubtitle(p))}</small></div></div>`;}
function picker(c){return `<label class="ui-picker">${avatar(c.pet,'ui-avatar-small')}<strong>${E(c.state.current==='all'?'全部':c.pet?.name||'宠物')}</strong><span class="ui-down"></span><select id="petpick" aria-label="选择宠物">${c.state.pets.map(p=>`<option value="${E(p.id)}" ${p.id===c.state.current?'selected':''}>${E(p.name)}</option>`).join('')}<option value="all" ${c.state.current==='all'?'selected':''}>全部宠物</option></select></label>`;}
function top(c,title,back,more=false){return `<div class="ui-status">${onb(3109)}</div><header class="ui-header ${back||title!=='POMEPET'?'ui-centered':''}">${back?`<button data-go="${back}" class="ui-back" aria-label="返回">${onb(3988)}</button>`:''}${title==='POMEPET'?image('1667:3423','ui-logo'):`<h1>${E(title)}</h1>`}${title==='POMEPET'?picker(c) :''}</header>`;}
function nav(page){const surface=page==='today'?'3576':page==='ledger'?'2929':page==='profile'?'3319':'3895',active=page==='today'?'3577':page==='ledger'?'2930':page==='profile'?'3320':'3896';return `<nav class="ui-nav ui-nav-${page}" aria-label="主导航">${ledgerAsset('744','ui-nav-surface')}${[['today','今日','3589'],['ledger','记账','3579'],['profile','档案','3582'],['mine','我的','3585']].map(([p,n,id])=>`<button data-go="${p}" ${page===p?'aria-current="page"':''} class="${page===p?'active':''}">${page===p?ledgerAsset('745','ui-nav-active'):''}${ledgerAsset(({today:'757',ledger:'747',profile:'750',mine:'753'})[p],'ui-nav-icon')}<span>${n}</span></button>`).join('')}</nav><div class="ui-home-indicator">${onb(3105)}</div>`;}
const shell=(html,page,cls='')=>`<section class="ui-canvas ui-${page} ${cls}">${html}</section>`;
const empty=t=>`<div class="ui-empty">${E(t)}</div>`;
const isToday=t=>new Date(t).toDateString()===new Date().toDateString();
const due=t=>new Date(t).getTime()<=new Date(new Date().setHours(23,59,59,999)).getTime();
const daysAway=t=>Math.round((new Date(new Date(t).setHours(0,0,0,0))-new Date(new Date().setHours(0,0,0,0)))/86400000);
const iconMap={'遛狗':'3063','喂食':'3060','换水':'3061','排便':'3062','散步':'3063','体重':'3064','驱虫':'3097','疫苗':'3065','用药':'3066','剪指甲':'3067','日记':'3068','照片':'3069','洗澡':'3070','梳毛':'3071','刷牙':'3096'};
const activityIcon=(a,c)=>{const custom=c?.state.customActivities?.find(x=>x.name===a);return custom?.emoji?`<i class="ui-custom-emoji" aria-hidden="true">${E(custom.emoji)}</i>`:image('1667:'+(iconMap[a]||'3068'));};
function timeline(c){const list=c.visible(c.state.records).filter(r=>c.filter==='全部'||c.activities.find(a=>a[0]===r.activity)?.[1]===c.filter).sort((a,b)=>new Date(b.at)-new Date(a.at)||new Date(b.created)-new Date(a.created));if(!list.length)return empty(c.filter==='全部'?'还没有记录，记下它的第一个小日常吧。':'这个分类还没有记录。');const groups=new Map();for(const r of list){const key=local(r.at).slice(0,10);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}return `<div class="ui-timeline">${[...groups].map(([key,rows])=>{const yesterday=new Date();yesterday.setDate(yesterday.getDate()-1);const heading=(isToday(key+'T12:00')?'今天 · ':new Date(key+'T12:00').toDateString()===yesterday.toDateString()?'昨天 · ':'')+day(key+'T12:00');return `<section class="ui-record-group"><h2>${heading}</h2>${rows.map(r=>{let summary=r.product&&r.value?`${r.product} ${r.value}${r.unit||''}`:r.value?`${r.value}${r.activity==='体重'?' kg':r.unit||''}`:r.product||r.note||'已记录';if(r.activity==='体重'){const previous=c.state.records.filter(x=>x.petId===r.petId&&x.activity==='体重'&&new Date(x.at)<new Date(r.at)).sort((a,b)=>new Date(b.at)-new Date(a.at))[0];if(previous){const change=Number(r.value)-Number(previous.value);summary+=` · 较上次 ${change>=0?'+':''}${change.toFixed(2)} kg`;}}return `<button class="ui-record" data-detail="${E(r.id)}"><span class="ui-record-icon">${image('1667:3526','ui-icon-bg')}${activityIcon(r.activity,c)}</span><span class="ui-record-copy"><strong>${E(r.title||label(r.activity))}</strong><small>${E(summary)}${c.state.current==='all'?' · '+E(c.name(r.petId)):''}</small></span><time>${clock(r.at)}</time>${chevron()}</button>`;}).join('')}</section>`;}).join('')}</div>`;}
function recordHeader(c){return `<div class="ui-record-toolbar"><div class="ui-record-title"><h2>生活记录</h2><button data-add="today" class="ui-add">${image('1667:3596','ui-button-surface')}${image('1667:3612')}<span>新增</span></button></div><div class="ui-filter" role="group" aria-label="记录分类">${['全部','日常','健康','回忆'].map((x,i)=>`<button data-filter="${x}" aria-pressed="${c.filter===x}" class="${c.filter===x?'active':''}">${image('1667:'+(c.filter===x?'3506':i===3?'3515':'3509'),'ui-pill-surface')}<span>${x}</span></button>`).join('')}</div></div>`;}
const floatingAdd=page=>`<div class="ui-floating-wrap ui-floating-${page}"><button class="ui-floating-add" data-add="${page}" aria-label="${page==='plans'?'悬浮新建安排':'悬浮新增记录'}" title="${page==='plans'?'新建安排':'新增记录'}">＋</button></div>`;
function today(c){const pending=c.visible(c.state.tasks).filter(t=>t.status==='pending').sort((a,b)=>new Date(a.at)-new Date(b.at));const tasks=pending.filter(t=>due(t.at)),future=pending.filter(t=>!due(t.at));const shown=[...tasks,...future].slice(0,3);return shell(top(c,'POMEPET')+`<section class="ui-care-paper">${image('1667:3466','ui-paper-bg')}<div class="ui-paper-date"><strong>${day(Date.now())}</strong><b>${new Date().toLocaleDateString('zh-CN',{weekday:'long'})}</b></div>${c.pet?.kind==='狗狗'?'<img class="ui-asset ui-paper-dog" src="./assets/dog/1700-1947.svg" alt="狗狗贴纸">':image('1667:3524','ui-paper-cat')}${image('1667:3467','ui-paper-note')}${image('1667:3550','ui-paper-tape')}<button class="ui-paper-all" data-go="plans">全部安排 ›</button><div class="ui-paper-tasks">${shown.length?shown.map(t=>`<div><button class="ui-paper-task" data-task="${E(t.id)}"><span class="ui-circle"></span><strong>${E(label(t.activity))}</strong><small>${due(t.at)?isToday(t.at)?'今天到期':'已逾期':daysAway(t.at)+'天后'}</small></button><button data-complete="${E(t.id)}">完成</button></div>`).join(''):'<p class="ui-paper-empty">今天没有待办<br>好好享受一起的时光。</p>'}</div><small class="ui-coming">${future.slice(shown.filter(t=>!due(t.at)).length).length?'即将到来：'+future.slice(shown.filter(t=>!due(t.at)).length).slice(0,2).map(t=>E(label(t.activity))+daysAway(t.at)+'天后').join(' / '):'守护它的每一个小日常'}</small></section>`+recordHeader(c)+timeline(c)+nav('today')+floatingAdd('today'),'today');}
function taskCard(t,c,future=false){return `<div class="ui-task"><button class="ui-task-copy" data-task="${E(t.id)}"><strong>${E(label(t.activity))}</strong><small>${future?day(t.at):clock(t.status==='done'?t.completedAt:t.at)} · ${E(c.name(t.petId))}</small></button>${t.status==='pending'&&!future?`<button class="ui-task-complete" data-complete="${E(t.id)}">完成</button>`:`<button class="ui-task-distance" data-task="${E(t.id)}">${t.status==='done'?'已完成':daysAway(t.at)+'天'}</button>`}</div>`;}
function plansContent(c){const tasks=c.visible(c.state.tasks).filter(t=>t.status===c.taskTab).sort((a,b)=>c.taskTab==='done'?new Date(b.completedAt)-new Date(a.completedAt):new Date(a.at)-new Date(b.at));const current=tasks.filter(t=>due(t.at)),future=tasks.filter(t=>!due(t.at));return `<div class="ui-plan-tabs">${['pending','done'].map((x,i)=>`<button data-tab="${x}" class="${c.taskTab===x?'active':''}">${i?'已完成':'待办'}</button>`).join('')}</div><div class="ui-plan-summary"><h2>${c.taskTab==='done'?'已完成照护 · '+tasks.length+' 项':'今日清单 · '+current.length+' 项待办'}</h2><p>按时完成，守护${E(c.pet?.name||'它')}的小日常。</p></div><div class="ui-plan-list">${c.taskTab==='done'?(tasks.length?tasks.map(t=>taskCard(t,c)).join(''):empty('还没有完成的安排')):`<h2>今天 · ${day(Date.now())}</h2>${current.length?current.map(t=>taskCard(t,c)).join(''):empty('今天没有待办')}<h2>未来安排</h2>${future.length?future.map(t=>taskCard(t,c,true)).join(''):empty('还没有未来安排')}`}</div>`;}
function plans(c){return shell(top(c,'照护安排','today')+`<div class="ui-arrangements-picker">${picker(c)}</div>`+plansContent(c)+`<button class="ui-arrangements-add" data-add="plans" aria-label="新建安排">＋ 新建安排</button><div class="ui-form-home">${onb(3105)}</div>`+floatingAdd('plans'),'plans');}
function profile(c){if(c.state.current==='all'||!c.pet)return shell(top(c,'档案')+empty('请先选择一只宠物查看档案。')+`<div class="ui-profile-picker">${picker(c)}</div>`+nav('profile'),'profile');const p=c.pet,idx=c.state.pets.findIndex(x=>x.id===p.id),prev=c.state.pets[(idx-1+c.state.pets.length)%c.state.pets.length],next=c.state.pets[(idx+1)%c.state.pets.length];const weights=c.state.records.filter(r=>r.petId===p.id&&r.activity==='体重').sort((a,b)=>new Date(b.at)-new Date(a.at));const vaccine=c.state.records.filter(r=>r.petId===p.id&&['疫苗','驱虫'].includes(r.activity)).sort((a,b)=>new Date(b.at)-new Date(a.at))[0],medical=c.state.records.filter(r=>r.petId===p.id&&['用药','就诊','复诊'].includes(r.activity)).sort((a,b)=>new Date(b.at)-new Date(a.at))[0];return shell(top(c,'档案')+`<div class="ui-profile-hero">${p.profilePhoto||p.avatar?`<label class="ui-profile-upload" aria-label="更换${E(p.name)}的档案照片"><img class="ui-profile-photo" src="${E(p.profilePhoto||p.avatar)}" alt="${E(p.name)}"><input id="profilePhotoInput" type="file" accept="image/*" hidden></label>`:`<label class="ui-profile-upload ui-profile-empty" aria-label="添加宠物档案照片"><img src="./assets/profile-empty/1698-1944.svg" alt="" class="ui-profile-placeholder"><img src="./assets/profile-empty/1698-1943.svg" alt="添加照片" class="ui-profile-upload-icon"><input id="profilePhotoInput" type="file" accept="image/*" hidden></label>`}${c.state.pets.length>1?`${c.state.pets.length>2?`<button class="ui-neighbor prev" data-pet="${E(prev.id)}">${avatar(prev)}<small>${E(prev.name)}</small>${image('1667:3335','ui-neighbor-arrow')}</button>`:''}<button class="ui-neighbor next" data-pet="${E(next.id)}">${image('1667:3334','ui-neighbor-arrow')}${avatar(next)}<small>${E(next.name)}</small></button>`:''}<h2>${E(p.name)}</h2><p>${E(petSubtitle(p))}</p><p class="ui-companion">${companionDays(p.arrival)!==null?'我们已经彼此陪伴'+companionDays(p.arrival)+'天啦':'填写到家日，记录我们的陪伴时光'}</p></div><div class="ui-profile-content"><h2>健康概览</h2><button class="ui-profile-row" data-go="health"><span><strong>最近体重</strong><small>${weights[0]?'更新于 '+day(weights[0].at):'暂无体重记录'}</small></span><b>${weights[0]?E(weights[0].value)+' kg':'—'}</b></button><button class="ui-profile-row" data-health-filter="vaccine"><span><strong>疫苗与驱虫</strong><small>${vaccine?'更新于 '+day(vaccine.at):'暂无记录'}</small></span>${chevron()}</button><button class="ui-profile-row" data-health-filter="medical"><span><strong>用药与就诊</strong><small>${medical?day(medical.at):'暂无记录'}</small></span>${chevron()}</button><h2>一起长大的日子</h2><button class="ui-album-card" data-go="album"><strong>成长照片合集</strong><small>记录每个重要时刻</small></button><button class="ui-pet-edit-link" data-go="petedit">编辑宠物资料 ${chevron()}</button></div>`+nav('profile'),'profile');}
const menuRow=(text,attrs)=>`<button class="ui-menu-row" ${attrs}><span>${text}</span>${chevron()}</button>`;
function mine(c){return shell(top(c,'我的')+`<div class="ui-mine-content"><h2>我的宠物</h2><div class="ui-mine-pets">${c.state.pets.map(p=>`<div class="ui-pet-swipe" data-swipe-pet="${E(p.id)}"><button class="ui-pet-delete" data-delete-pet="${E(p.id)}" aria-label="删除${E(p.name)}的档案" hidden>删除</button><button class="ui-mine-pet" data-pet="${E(p.id)}" data-open-profile title="左滑显示删除，也可按左方向键">${avatar(p)}<span><strong>${E(p.name)}</strong><small>${E(petSubtitle(p))}</small></span>${chevron()}</button></div>`).join('')||empty('还没有宠物')}<button class="ui-pet-new" data-go="petform">＋ 添加宠物</button></div>${c.state.deletedPets?.length?`<button class="ui-pet-restore" id="restoreDeletedPet">恢复最近删除的档案</button>`:""}<h2 class="ui-settings-title">设置</h2><div class="ui-menu">${menuRow('注册入口','data-go="login"')}${menuRow('事项管理','id="manageCare"')}${menuRow('提醒与通知','id="notificationSettings"')}</div><h2 class="ui-backup-title">数据与备份</h2><div class="ui-menu ui-backup-menu">${menuRow('导出完整备份','id="export"')}<label class="ui-menu-row" tabindex="0"><span>恢复备份</span>${chevron()}<input id="restore" type="file" accept="application/json,.json" hidden></label>${menuRow('导出记录CSV','id="exportCSV"')}</div><div class="ui-storage-note"><strong>数据保存在当前设备</strong><small>定期备份，让每一条小日常安心留存</small></div><div class="ui-menu ui-about-menu">${menuRow('隐私与权限','id="privacyInfo"')}${menuRow('关于POMEPET','id="aboutInfo"')}</div><p class="ui-footer">POMEPET · 记下它的每个小日常</p></div>`+nav('mine'),'mine');}
function choose(c){const sections=[['日常生活',['喂食','换水','排便',c.pet?.kind==='狗狗'?'遛狗':'散步']],['健康照护',['体重','驱虫','疫苗','用药']],['清洁护理',['洗澡','梳毛','刷牙','剪指甲']],['成长回忆',['日记','照片']]];const custom=c.state.customActivities||[];return shell(`<div class="ui-sheet-underlay" aria-hidden="true">${top(c,'POMEPET')}${plansContent(c)}</div><div class="ui-scrim" data-go="${c.origin}"></div><section class="ui-create-sheet" role="dialog" aria-modal="true" aria-label="创建记录"><div class="ui-sheet-heading"><h1>创建记录</h1><button data-go="${c.origin}" aria-label="关闭">×</button></div><div class="ui-sheet-pet">${avatar(c.pet)}<div><strong>${E(c.pet?.name)}</strong><small>${E(petSubtitle(c.pet))}</small></div></div><label class="ui-search">${image('1667:3043','ui-search-bg')}<input id="activitySearch" placeholder="搜索记录事项…" aria-label="搜索记录事项"></label><div class="ui-activity-sections">${[...sections,...(custom.length?[['自定义事项',custom.map(x=>x.name)]]:[])].map(([title,items])=>`<section class="ui-activity-group"><h2>${title}</h2><div class="ui-activity-grid">${items.map(a=>`<button data-activity="${E(a)}" aria-label="${E(a)}">${image('1667:3044','ui-activity-bg')}${activityIcon(a,c)}<span>${E(a)}</span></button>`).join('')}</div></section>`).join('')}</div><button class="ui-custom" id="newCustom">${image('1667:3058','ui-custom-bg')}<span>添加自定义事项</span></button><div class="ui-sheet-indicator">${onb(3105)}</div></section>`,'choose');}
function operation(c){return shell(top(c,label(c.activity),'choose',true)+petCard(c.pet)+`<h2 class="ui-operation-heading">你想做什么？</h2><button class="ui-operation-card" data-mode="record">${image('1667:3068')}<div><strong>记一次</strong><p>已经做过了，记下实际情况</p></div></button><button class="ui-operation-card ui-operation-plan" data-mode="schedule">${image('1667:3360')}<div><strong>安排一次</strong><p>还没做，设定时间提醒我</p></div></button><div class="ui-form-home">${onb(3105)}</div>`,'operation');}
function schedule(c){const t=c.page==='taskdetail'?c.state.tasks.find(t=>t.id===c.completeId):null;if(t?.status==='done')return null;const a=t?.activity||c.activity,initial=t?.at||new Date(Date.now()+86400000),repeat=t?.repeat||'interval';return shell(top(c,'计划'+(a==='驱虫'?'驱虫':a),t?'plans':c.origin==='plans'?'plans':'operation')+petCard(t?c.state.pets.find(p=>p.id===t.petId):c.pet)+`<form id="scheduleForm" class="ui-schedule-form"><input type="hidden" name="petId" value="${E(t?.petId||c.pet?.id)}"><label class="ui-schedule-date">${image('1667:3379','ui-surface')}<strong>计划时间</strong><span id="scheduleDateDisplay">${day(initial)} ${clock(initial)}</span><input type="datetime-local" name="at" required aria-label="计划时间" value="${local(initial)}"></label><div class="ui-repeat-label">重复方式</div><div class="ui-repeat-group" role="group" aria-label="重复方式">${['once','fixed','interval'].map((x,i)=>`<label><input type="radio" name="repeat" value="${x}" ${repeat===x?'checked':''}><span>${['单次','固定周期','完成后间隔'][i]}</span></label>`).join('')}</div><label class="ui-days-row">${image('1667:3380','ui-surface')}<strong>间隔天数</strong><div><input name="days" type="number" min="1" max="365" value="${t?.days||30}" aria-label="间隔天数">天</div></label><label class="ui-notify-row">${image('1667:3381','ui-surface')}<strong>通知我</strong><input name="remind" type="checkbox" ${t?.remind===false?'':'checked'} role="switch" aria-label="应用内提醒"><span class="ui-toggle"></span></label><label class="ui-schedule-note">${image('1667:3382','ui-surface')}<span>备注（可选）</span><textarea name="note" placeholder="记录需要注意的事情…" maxlength="500">${E(t?.note||'')}</textarea></label><label class="ui-system-notify"><input id="systemNotify" type="checkbox"><span>开启系统通知</span></label><small class="ui-notification-limit">浏览器打开时提供提醒</small><p class="ui-schedule-hint">仅提醒你设置的安排，周期可随时修改</p><button type="submit" class="ui-schedule-save">${image('1667:3387','ui-surface')}<span>保存安排</span></button>${t?`<button type="button" class="ui-finish-task" data-complete="${E(t.id)}">完成本次安排</button><button type="button" class="ui-cancel-task" id="cancelTask">取消安排</button>`:''}</form><div class="ui-form-home">${onb(3105)}</div>`,'scheduleform');}
function complete(c){const t=c.state.tasks.find(t=>t.id===c.completeId);if(!t)return null;const time=local(Date.now());return shell(top(c,'完成'+(t.activity==='驱虫'?'驱虫':t.activity),'taskdetail',true)+petCard(c.state.pets.find(p=>p.id===t.petId))+`<form id="completionForm" class="ui-completion-form"><div class="ui-complete-datetime"><label>${image('1682:431','ui-surface')}<strong>日期</strong><span id="completionDateDisplay">${day(Date.now())}</span><input name="date" type="date" required value="${time.slice(0,10)}" aria-label="实际完成日期">${chevron()}</label><label>${image('1682:432','ui-surface')}<strong>时间</strong><input name="time" type="time" required value="${time.slice(11)}" aria-label="实际完成时间">${chevron()}</label></div>${['驱虫','疫苗','用药'].includes(t.activity)?`<label class="ui-product-row">${image('1682:417','ui-surface')}<strong>产品名称</strong><input name="product" placeholder="选择或输入产品" value="${E(t.product||'')}" aria-label="产品名称">${chevron()}</label>`:`<label class="ui-product-row">${image('1682:417','ui-surface')}<strong>${t.activity==='体重'?'体重 kg':'实际情况'}</strong><input name="${t.activity==='体重'?'value':'product'}" type="${t.activity==='体重'?'number':'text'}" ${t.activity==='体重'?'step="0.01" min="0.01" required':''} placeholder="填写实际情况" aria-label="实际情况"></label>`}<label class="ui-complete-note">${image('1682:419','ui-surface')}<strong>备注</strong><textarea name="note" maxlength="500" placeholder="记录它今天的状态…"></textarea></label><div class="ui-complete-photo-title">照片（可选）</div><div class="ui-complete-photos"><div id="photos">${c.photos.map(p=>`<img src="${E(p)}" alt="记录照片">`).join('')}</div><label class="ui-photo-upload" aria-label="添加照片">${image('1682:420','ui-surface')}${image('1682:422')}<input id="photoInput" type="file" accept="image/*" multiple hidden></label><label class="ui-photo-upload" aria-label="再添加照片">${image('1682:421','ui-surface')}<span>＋</span><input class="ui-extra-photo" type="file" accept="image/*" multiple hidden></label></div>${t.repeat!=='once'?`<div class="ui-next-card">${image('1681:230','ui-surface')}<div class="ui-next-heading"><strong>下次安排</strong><button type="button" id="adjustNext">调整 ${chevron()}</button></div><b id="nextDate"></b><small id="nextRule"></small><input name="nextAt" type="datetime-local" aria-label="调整下次安排" hidden></div>`:'<div class="ui-next-card ui-once-note"><strong>本次为单次安排</strong><p>完成后将保存生活记录。</p></div>'}<p class="ui-complete-hint">确认后生成生活记录${t.repeat==='once'?'。':'，并更新下次安排。'}</p><button class="ui-complete-save" type="submit">${image('1681:236','ui-surface')}<span>确认完成</span></button></form><div class="ui-form-home">${onb(3105)}</div>`,'completion');}
export function renderScreen(page,c){return ({petedit:petEditor,today,plans,profile,mine,choose,operation,scheduleform:schedule,taskdetail:schedule,recordform:complete}[page])?.({...c,page})??null;}
export function scaleScreens(){const canvas=document.querySelector('.ui-canvas');if(canvas){const factor=Math.min(1,innerWidth/402);canvas.style.zoom=factor;document.documentElement.style.setProperty('--ui-scale',factor);document.querySelectorAll('.ui-nav,.ui-home-indicator').forEach(el=>el.style.transform=`translateX(-50%) scale(${factor})`);const wrap=document.querySelector('.ui-floating-wrap');if(wrap){wrap.style.transform=`translateX(-50%) scale(${factor})`;wrap.style.bottom=`calc(${(wrap.classList.contains('ui-floating-today')?116:32)*factor}px + env(safe-area-inset-bottom))`;} }}
export {top,petCard,shell,onb,chevron,picker};

export const ledgerAsset=(id,cls='')=>`<img class="ui-asset ${cls}" src="./assets/ledger/1690-${id}.svg" alt="" data-figma-asset="1690:${id}">`;
export {nav};




